import { Module, forwardRef } from "@nestjs/common";
import { ConnectQuestService } from "./connect-quest.service";
import { ConnectQuestController} from "./connect-quest.controller";
import { CachingModule } from "../caching/caching.module";

/**
 * Modul: ConnectQuestModule
 *
 * Dieses Modul kapselt die Logik zur Speicherung und Abrufung von, für die Verbindung von einer
 * Quest benötigten Daten: JWT, CourseProgressId und ID des aufrufenden Usersnüber einen One-Time-PIN.
 * Es bietet insbesondere folgende Funktionalitäten:
 *
 * - Generierung eines temporären PINs (4-stellig)
 * - Zwischenspeicherung von Token, User-ID und Progress-ID im Cache
 * - Abfrage gespeicherter PINs und zugehöriger Nutzdaten
 *
 * Der PIN-Mechanismus dient zur sicheren und temporären Verknüpfung von Benutzern
 * mit einer laufenden Aktion, z. B. einem Onboarding oder einer spezifischen Quest.
 *
 * Abhängigkeiten:
 * - Nutzt das CachingModule für die Kommunikation mit Redis
 */
@Module({
	// Importiert CachingModule, um Redis-basiertes Speichern zu ermöglichen
	imports: [forwardRef(() => CachingModule)],

	// Registriert den ConnectQuestService als Provider für die Geschäftslogik
	providers: [ConnectQuestService],

	// Definiert den zugehörigen REST-Controller zur Bereitstellung der Endpunkte
	controllers: [ConnectQuestController],

	// Exportiert den Service für die Nutzung in anderen Modulen
	exports: [ConnectQuestService],
})
export class ConnectQuestModule {}
